sudo tee /etc/kea/kea-dhcp4.conf <<'EOF'   # 🟡 verify exact path for your install; this is illustrative structure, not a copy-paste-guaranteed complete file — consult your version's full schema
{
  "Dhcp4": {
    "interfaces-config": { "interfaces": [ "eth0" ] },
    "lease-database": { "type": "memfile" },
    "valid-lifetime": 3600,
    "subnet4": [
      {
        "subnet": "192.168.1.0/24",
        "pools": [ { "pool": "192.168.1.100 - 192.168.1.200" } ],
        "option-data": [
          { "name": "routers", "data": "192.168.1.1" },
          { "name": "domain-name-servers", "data": "192.168.1.1" }
        ],
        "reservations": [
          { "hw-address": "aa:bb:cc:dd:ee:ff", "ip-address": "192.168.1.50" }
        ]
      }
    ]
  }
}
EOF
sudo systemctl restart kea-dhcp4    # 🟠 (verify exact unit name)

journalctl -u kea-dhcp4 -b        # 🟢 confirm clean startup, subnet loaded without error
# from a client on that subnet:
sudo dhclient -r ; sudo dhclient   # 🟡 (on a RHEL 10 client, this is via NetworkManager's internal client instead — use `nmcli connection up` to trigger a renewal rather than assuming a standalone dhclient binary exists)
ip addr show                       # 🟢 confirm the client received an address from the expected pool
